    @EventHandler( payloadType=CreateRiskEvent.class )
    public void handle( CreateRiskEvent event) {
	    LOGGER.info("handling CreateRiskEvent - " + event );
	    Risk entity = new Risk();
            entity.setRiskId( event.getRiskId() );
            entity.setName( event.getName() );
            entity.setDescription( event.getDescription() );
            entity.setInherentRiskScore( event.getInherentRiskScore() );
            entity.setResidualRiskScore( event.getResidualRiskScore() );
            entity.setCategory( event.getCategory() );
            entity.setImpact( event.getImpact() );
            entity.setLikelihood( event.getLikelihood() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllRisk( entity );
    }

