    /**
     * Method to retrieve the Risk via an RiskPrimaryKey.
     * @param 	id Long
     * @return 	Risk
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Risk handle( FindRiskQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getRiskId() );
    }
    
    /**
     * Method to retrieve a collection of all Risks
     *
     * @param	query	FindAllRiskQuery 
     * @return 	List<Risk> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Risk> handle( FindAllRiskQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindRisk,
 * but only if the id matches
 *
 * @param		entity	Risk
 */
	protected void emitFindRisk( Risk entity ) {
		LOGGER.info("handling emitFindRisk" );
		
	    queryUpdateEmitter.emit(FindRiskQuery.class,
	                            query -> query.getFilter().getRiskId().equals(entity.getRiskId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllRisk
	 * 
	 * @param		entity	Risk
	 */
	protected void emitFindAllRisk( Risk entity ) {
		LOGGER.info("handling emitFindAllRisk" );
		
	    queryUpdateEmitter.emit(FindAllRiskQuery.class,
	                            query -> true,
	                            entity);
	}

